import 'auth_models.dart';
import '../security/security_models.dart';
import '../security/security_services.dart';
class RouteGuard { const RouteGuard([this.permissions]); final PermissionService? permissions; String? redirect(AuthSession session,String location) { if(session.status==AuthStatus.suspended||session.status==AuthStatus.deleted)return location=='/account-status'?null:'/account-status'; if(session.status==AuthStatus.sessionExpired)return '/auth/session-expired'; final protected=location.startsWith('/profile')||location.startsWith('/privacy')||location.startsWith('/seller/')||location.startsWith('/admin/'); if(protected&&session.status!=AuthStatus.loggedIn){if(location=='/seller/login'||location=='/admin/login')return null;return '/auth/login';} if(location.startsWith('/admin/')){final role=SecurityRole.values.byName(session.role.name);final needed=location.contains('audit')?Permission.viewAuditLog:location.contains('subscriptions')?Permission.manageSubscriptions:null;if(needed!=null&&!(permissions??LocalPermissionService()).hasPermission(role,needed))return '/forbidden';if(!{UserRole.admin,UserRole.superAdmin,UserRole.supportAdmin,UserRole.catalogAdmin,UserRole.moderationAdmin,UserRole.sellerVerificationAdmin}.contains(session.role))return '/forbidden';} if(location.startsWith('/seller/')&&session.role!=UserRole.seller)return '/forbidden'; return null; } }
